  "home.faq1q": "Wie lange dauert die Berichtserstellung?",
  "home.faq1a": "Die meisten Berichte sind innerhalb von 10 Minuten nach Eingabe der IČO fertig, abhängig von der Unternehmensgröße.",
  "home.faq2q": "Sind die Registerdaten aktuell?",
  "home.faq2a": "Ja, die Daten werden zum Zeitpunkt der Berichtserstellung direkt aus den Registern abgerufen.",
  "home.faq3q": "Welche Zahlungsmethoden akzeptieren Sie?",
  "home.faq3a": "Wir akzeptieren Kartenzahlungen (Visa, Mastercard, American Express), Apple Pay, Google Pay, PayPal und SEPA-Banküberweisung über Paddle.",
  "home.faq5q": "Was passiert, wenn der Bericht fehlschlägt?",
  "home.faq5a": "Wenn der Bericht aufgrund eines technischen Ausfalls der wichtigsten Staatsregister nicht erstellt werden kann, erstatten wir den vollen Betrag oder schreiben Ihnen ein Guthaben für einen neuen Bericht gut.",
  "home.faq6q": "Ist der Bericht rechtlich verbindlich?",
  "home.faq6a": "Nein. Der Bericht ist ein Informationsinstrument für Due Diligence und interne Risikobewertung. Er bietet eine glaubwürdige Grundlage für Entscheidungen, ersetzt aber keine Rechts- oder Steuerberatung.",
  "home.faq7q": "Kann ich den Bericht mit einem Mandanten teilen?",
  "home.faq7a": "Ja. Der Bericht ist ein Standard-PDF, das zum Teilen bereit ist — Sie können es an einen Mandanten senden, einer Akte beifügen oder archivieren. Es enthält kein Wasserzeichen oder Einschränkungen.",
  "home.faq8q": "Was ist der Verifa Score?",
  "home.faq8a": "Verifa Score ist eine 5-Säulen-Risikobewertung auf einer Skala von 0–100 mit Kategorie AAA/A/B/C. Es umfasst finanzielle Stabilität, rechtliches Risiko, Steuerdisziplin, Insolvenzverfahren und forensische Indikatoren.",
  "home.faq9q": "Enthält der Bericht ein automatisiertes Gutachten des Unternehmens?",
  "home.faq9a": "Ja, jeder Bericht enthält eine automatisierte Management-Zusammenfassung in natürlicher Sprache, die Kernrisiken und Empfehlungen identifiziert. Das Gutachten lässt sich direkt in eine Akte oder einen Mandantenbericht einfügen — geeignet für Anwälte, Notare und Steuerberater.",
  "home.faq10q": "Kann der Bericht einen Konkurs vorhersagen?",
  "home.faq10a": "Ja, der Bericht enthält einen Insolvency Score — ein algorithmisches Modell, das die Wahrscheinlichkeit eines Konkurses auf Basis von Altman Z-Score, Piotroski F-Score, Liquidität, Verschuldung und Trends schätzt. Ergänzt durch Trends der Kennzahlen im Zeitverlauf.",
  "home.faq11q": "Warnt mich der Bericht vor Steuerschulden?",
  "home.faq11a": "Ja, der Bericht enthält eine Staatsschulden-Warnung — Hinweis auf Steuer- und Sozialversicherungsrückstände. Wenn ein Unternehmen dem Staat schuldet, ist das Rechnungsausfallrisiko hoch. Das System prüft auch das Insolvenzregister.",
