  "home.statRegisters": "registrov",
  "home.statAvgTime": "průměrný čas reportu",
  "home.statScoreRange": "Verifa Score rozsah",
  "home.statReport": "Komplexní report",
  "home.faqTitle": "Časté otázky",
  "home.faq1q": "Jak dlouho trvá zpracování reportu?",
  "home.faq1a": "Většina reportů je hotových do 10 minut od zadání IČO, v závislosti na velikosti společnosti.",
  "home.faq2q": "Jsou data z rejstříků aktuální?",
  "home.faq2a": "Ano, data jsou získávána přímo z rejstříků v čase vygenerování reportu.",
  "home.faq3q": "Jaké platobné metódy akceptujete?",
  "home.faq3a": "Prijímame platby kartou (Visa, Mastercard, American Express), Apple Pay, Google Pay, PayPal a SEPA bankový prevod cez Paddle.",
  "home.faq5q": "Co ak report zlyhá?",
  "home.faq5a": "Ak z důvodu technického výpadku hlavných štátnych registrov nebude možné report vygenerovať, vrátime vám plnú sumu alebo pripíšeme kredit na nový report.",
  "home.faq6q": "Je report právne záväzný?",
  "home.faq6a": "Nie. Report je informačný nástroj pre due diligence a interné posúdenie rizika. Poskytuje dôveryhodný podklad pre rozhodovanie, ale nenahrádza právne alebo daňové poradenstvo.",
  "home.faq7q": "Môžem report zdieľať s klientom?",
  "home.faq7a": "Áno. Report je štandardné PDF pripravené na zdieľanie — môžete ho poslať klientovi, priložiť do spisu alebo archivovať. Neobsahuje vodoznak ani obmedzenia.",
  "home.faq8q": "Čo je Verifa Score?",
  "home.faq8a": "Verifa Score je 5-pilierové hodnotenie rizika firmy na stupnici 0–100 s kategóriou AAA/A/B/C. Zahŕňa finančnú stabilitu, právne riziko, daňovú disciplínu, insolvenčné konania a forenzné indikátory.",
  "home.faq9q": "Obsahuje report automatizovaný posudok firmy?",
  "home.faq9a": "Áno, každý report obsahuje automatizované manažérske zhrnutie v prirodzenom jazyku, ktoré identifikuje kľúčové riziká a odporúčania. Posudok je priamo vložiteľný do spisu alebo správy pre klienta — vhodné pre právnikov, notárov a účtovníkov.",
  "home.faq10q": "Vie report predpovedať bankrot firmy?",
  "home.faq10a": "Áno, report obsahuje Insolvency Score — algoritmický model, ktorý odhaduje pravdepodobnosť úpadku na základe Altman Z-Score, Piotroski F-Score, likvidity, zadlženosti a trendov. Doplnený o trendy kľúčových ukazovateľov v čase.",
  "home.faq11q": "Upozorní ma report na daňové dlhy firmy?",
  "home.faq11a": "Áno, report obsahuje alert na štátne pohľadávky — upozornenie na daňové dlhy, sociálnu a zdravotné poisťovne. Ak firma dlží štátu, je vysoké riziko nezaplatenia faktúry. Systém tiež kontroluje Register úpadcov a insolvenčný register.",
  "home.navFeatures": "Funkcie",
  "home.navPricing": "Cenník",
  "home.ctaStart": "Začať bez záväzkov →",
  "home.ctaStartNow": "Začať teraz →",
  "home.whoIsItFor": "Pre koho je Verifa",
  "home.buy": "Kúpiť",
