  "home.faq10a": "Igen, a jelentés tartalmaz egy csődkockázati mutatót (Insolvency Score) – egy algoritmikus modellt, amely az Altman Z-Score, a Piotroski F-Score, a likviditás, a tőkeáttétel és a trendek alapján megbecsüli a csődkockázatot. Ezt a kulcsfontosságú mutatók időbeli alakulásának trendjei egészítik ki.",
  "home.faq10q": "Előre jelzi-e a jelentés a vállalat csődjét?",
