  "home.faq6a": "Nem. A jelentés egy információs eszköz a due diligence és a belső kockázatértékelés céljára. Hitelképes alapot biztosít a döntéshozatishoz, de nem helyettesíti a jogi vagy adóügyi tanácsadást.",
  "home.faq6q": "Jerövel bíró dokumentum a jelentés?",
