  "home.faq8q": "Mi az a Verifa Score?",
  "home.faq9a": "Igen, minden jelentés tartalmaz egy természetes nyelven megírt, automatizált vezetői összefoglalót, amely azonosítja a kulcsfontosságú kockázatokat és javaslatokat tesz. Az értékelés közvetlenül beilleszthető az ügyfél aktájába vagy jelentésébe – alkalmas ügyvédek, közjegyzők és könyvelők számára.",
