  "home.ri1Title": "Podsumowanie menedżerskie",
  "home.ri1Desc": "Zautomatyzowana opinia w języku naturalnym, która identyfikuje kluczowe ryzyka i rekomendacje. Gotowa do włączenia do akt lub raportu dla klienta.",
  "home.ri2Title": "Mapa ryzyka nadużyć",
  "home.ri2Desc": "Wizualna sygnalizacja świetlna dla 7 kategorii ryzyka — od analizy forensycznej po rejestry prawne. Od razu widać, gdzie występuje problem.",
  "home.ri3Title": "Prognoza upadłości",
  "home.ri3Desc": "Model algorytmiczny szacujący ryzyko bankructwa wraz z trendami. Wiesz wcześniej, czy partner będzie w stanie opłacić faktury.",
  "home.ri4Title": "Alert dotyczący należności publicznoprawnych",
  "home.ri4Desc": "Powiadomienia o zaległościach podatkowych oraz w ZUS i NFZ. Jeśli firma zalega państwu, istnieje wysokie ryzyko braku płatności.",
  "home.ri5Title": "Opinia biegłego rewidenta & Going Concern",
  "home.ri5Desc": "Rodzaj opinii audytorskiej oraz ostrzeżenia dotyczące kontynuacji działalności. Kluczowe dla weryfikacji stabilności firmy.",
  "home.ri6Title": "Ryzyka prawne & oś czasu",
  "home.ri6Desc": "Chronologiczny przegląd wydarzeń z dziennika urzędowego — upadłość, restrukturyzacja, zmiany w zarządzie — z kodowaniem kolorami według poziomu powagi.",
